
const $=(s,c=document)=>c.querySelector(s);const $$=(s,c=document)=>[...c.querySelectorAll(s)];
const navToggle=$('.nav-toggle'),navLinks=$('.nav-links');if(navToggle){navToggle.addEventListener('click',()=>{navLinks.classList.toggle('open');navToggle.setAttribute('aria-expanded',navLinks.classList.contains('open'))});$$('.nav-links a').forEach(a=>a.addEventListener('click',()=>navLinks.classList.remove('open')))}
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12});$$('.reveal').forEach(x=>observer.observe(x));
$$('.faq-item button').forEach(b=>b.addEventListener('click',()=>{const item=b.closest('.faq-item');item.classList.toggle('open');b.setAttribute('aria-expanded',item.classList.contains('open'))}));
async function handleForm(form){const status=$('.form-status',form);const data=Object.fromEntries(new FormData(form).entries());data.sent_at=new Date().toISOString();try{if(window.SITE_CONFIG?.formEndpoint){const r=await fetch(window.SITE_CONFIG.formEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok)throw new Error('Ошибка отправки');status.textContent='Заявка отправлена. Мы свяжемся с вами.';form.reset();}else{localStorage.setItem('stimul_food_last_request',JSON.stringify(data));const text=`STIMUL FOOD — новая заявка\nИмя: ${data.name||''}\nКонтакт: ${data.contact||''}\nФормат: ${data.format||''}\nКомментарий: ${data.message||''}`;await navigator.clipboard?.writeText(text);status.textContent='Заявка сохранена и текст скопирован. После подключения формы заявки будут поступать владельцу автоматически.';}}catch(e){status.textContent='Не удалось отправить. Данные сохранены в браузере; повторите попытку позже.';localStorage.setItem('stimul_food_last_request',JSON.stringify(data));}}
$$('form[data-lead]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();handleForm(f)}));

document.querySelectorAll('[data-client-link]').forEach(a=>{a.href=window.SITE_CONFIG?.clientSiteUrl||'#'});
document.querySelectorAll('.protected-download').forEach(a=>a.addEventListener('click',e=>{if(!sessionStorage.getItem('stimul_confidential')){const ok=confirm('Материал конфиденциален. Продолжая, вы подтверждаете адресное ознакомление и согласие не распространять его без разрешения Маркова Павла Андреевича.');if(!ok){e.preventDefault();return}sessionStorage.setItem('stimul_confidential','1')}}));
